import math

def tau(n):
    """Calculates the number of divisors of n."""
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def largest_odd_divisor(n):
    """Finds the largest odd divisor of n."""
    while n % 2 == 0:
        n //= 2
    return n

def N(n):
    """Calculates N(n) = tau(n) + tau(m), where m is the largest odd divisor of n."""
    m = largest_odd_divisor(n)
    return tau(n) + tau(m)

def is_exotic(n):
    """Checks if n is exotic: N(n) is twice an odd integer."""
    n_val = N(n)
    # Check if n_val = 2 * k where k is odd.
    # This means n_val must be even, and (n_val / 2) must be odd.
    if n_val % 2 != 0:
        return False

    k = n_val // 2
    return k % 2 != 0

def find_exotic_integers(limit):
    """Generates the sequence of exotic integers up to a given limit."""
    exotic_sequence = []
    for n in range(1, limit + 1):
        if is_exotic(n):
            exotic_sequence.append(n)
    return exotic_sequence

